const { withGradleProperties } = require("@expo/config-plugins");

// Read by android/app/build.gradle and AGP. android/gradle.properties is
// regenerated by every prebuild, so the values must come from a plugin.
const PROPERTIES = {
  // React Native's Fresco Image is no longer imported anywhere in src/.
  // Expo Image keeps GIF/WebP support through Glide, so these only remove the
  // unused Fresco decoders.
  "expo.gif.enabled": "false",
  "expo.webp.enabled": "false",
  "expo.webp.animated": "false",
  // Shrink resources against R8's optimized graph as well as the unoptimized
  // one. Build-time only; no runtime behavior.
  "android.r8.optimizedResourceShrinking": "true",
};

module.exports = function withSizeTunables(config) {
  return withGradleProperties(config, (config) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const existing = config.modResults.find(
        (item) => item.type === "property" && item.key === key,
      );
      if (existing) {
        existing.value = value;
      } else {
        config.modResults.push({ type: "property", key, value });
      }
    }
    return config;
  });
};
